package com.example.starter.spectrum.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 频谱协调相关配置。
 *
 * @param sharedEirpLimitMw 共享模式下，任意实际重叠的时间 × 频率 × 区域片段内，
 *                          生效租约 EIRP（mW，线性毫瓦）总和上限。
 */
@ConfigurationProperties(prefix = "spectrum")
public record SpectrumProperties(double sharedEirpLimitMw) {
}

package com.example.starter.spectrum.domain;

/**
 * 租约模式。
 */
public enum LeaseMode {

    /** 独占：与任一相遇租约冲突。 */
    EXCLUSIVE,

    /** 共享：仅在片段功率总和超限时冲突。 */
    SHARED
}

package com.example.starter.spectrum.domain;

/**
 * 租约生命周期状态。
 */
public enum LeaseStatus {

    /** 活动。 */
    ACTIVE,

    /** 已取消：取消时刻起失效，历史版本保留。 */
    CANCELLED
}

package com.example.starter.spectrum.domain;

/**
 * 租约领域事件类型。
 */
public enum EventType {

    /** 创建。 */
    CREATED,

    /** 修改（产生新版本）。 */
    MODIFIED,

    /** 取消（只改变未来有效性）。 */
    CANCELLED
}

