package com.example.starter.spectrum.service;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类，携带 HTTP 状态码与稳定错误码。
 */
public class LeaseServiceException extends RuntimeException {

    private final String code;
    private final HttpStatus status;

    /**
     * @param code    稳定错误码
     * @param status  映射的 HTTP 状态
     * @param message 面向调用方的错误说明
     */
    public LeaseServiceException(String code, HttpStatus status, String message) {
        super(message);
        this.code = code;
        this.status = status;
    }

    public String getCode() {
        return code;
    }

    public HttpStatus getStatus() {
        return status;
    }
}

package com.example.starter.spectrum.service;

import org.springframework.http.HttpStatus;

/**
 * 请求非法（参数区间不合法、区域集合为空等），映射 400。
 */
public class InvalidLeaseRequestException extends LeaseServiceException {

    public InvalidLeaseRequestException(String message) {
        super("INVALID_REQUEST", HttpStatus.BAD_REQUEST, message);
    }
}

package com.example.starter.spectrum.service;

import org.springframework.http.HttpStatus;

/**
 * 租约不存在，映射 404。
 */
public class LeaseNotFoundException extends LeaseServiceException {

    public LeaseNotFoundException(long leaseId) {
        super("LEASE_NOT_FOUND", HttpStatus.NOT_FOUND, "lease not found: " + leaseId);
    }
}

package com.example.starter.spectrum.service;

import org.springframework.http.HttpStatus;

/**
 * 乐观版本不匹配，映射 409。
 */
public class VersionConflictException extends LeaseServiceException {

    public VersionConflictException(long leaseId, Integer expected, int actual) {
        super("VERSION_CONFLICT", HttpStatus.CONFLICT,
                "version conflict for lease " + leaseId + ": expected " + expected + ", actual " + actual);
    }
}

package com.example.starter.spectrum.service;

import org.springframework.http.HttpStatus;

/**
 * 同一幂等键携带不同请求指纹，映射 409。
 */
public class IdempotencyConflictException extends LeaseServiceException {

    public IdempotencyConflictException(String requestId) {
        super("IDEMPOTENCY_CONFLICT", HttpStatus.CONFLICT,
                "requestId " + requestId + " was already used with different parameters");
    }
}

package com.example.starter.spectrum.service;

import com.example.starter.spectrum.domain.ConflictReport;
import org.springframework.http.HttpStatus;

/**
 * 候选租约与当前活动租约集合冲突（独占冲突或共享片段功率超限），映射 409，
 * 响应体携带冲突解释报告。
 */
public class LeaseConflictException extends LeaseServiceException {

    private final transient ConflictReport report;

    public LeaseConflictException(ConflictReport report) {
        super("LEASE_CONFLICT", HttpStatus.CONFLICT, "lease conflicts with active leases");
        this.report = report;
    }

    public ConflictReport getReport() {
        return report;
    }
}

