    /** 指定时刻活动快照：GET /api/leases/active?at=epochMillis（缺省为当前时刻）。 */
    @GetMapping("/api/leases/active")
    public List<LeaseResponse> activeSnapshot(@RequestParam(required = false) Long at) {
