/**
 * 事务结束后统一落幂等记录并回放/返回结果。
 * 失败结果以独立事务提交，保证同键同参重放得到首次结果。
 */
private LeaseResponse settle(String requestId, String fingerprint, TxOutcome outcome, long now) {
    if (outcome.replay() != null) {
        return replay(outcome.replay());
    }
    if (outcome.success() != null) {
        idempotencyRecorder.record(requestId, fingerprint, HttpStatus.OK.value(),
                null, null, outcome.success().leaseId(), now);
        return outcome.success();
    }
    String errorBody = outcome.report() != null ? toJson(outcome.report()) : null;
    idempotencyRecorder.record(requestId, fingerprint, outcome.httpStatus(),
            outcome.errorCode(), errorBody, null, now);
    throw toException(outcome);
}

